Equiv.Perm.card_of_cycleType_mul_eq : ∀ (α : Type u_1) [inst : DecidableEq α] [inst_1 : Fintype α] (m : Multiset ℕ),
  {g | g.cycleType = m}.card *
      ((Fintype.card α - m.sum).factorial * m.prod * ∏ n ∈ m.toFinset, (Multiset.count n m).factorial) =
    if m.sum ≤ Fintype.card α ∧ ∀ a ∈ m, 2 ≤ a then (Fintype.card α).factorial else 0
@Equiv.Perm.sign_of_cycleType : ∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] (f : Equiv.Perm α),
  Equiv.Perm.sign f = (-1) ^ (f.cycleType.sum + f.cycleType.card)
@Equiv.Perm.sum_cycleType : ∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] (σ : Equiv.Perm α),
  σ.cycleType.sum = σ.support.card
@Equiv.Perm.dvd_of_mem_cycleType : ∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] {σ : Equiv.Perm α}
  {n : ℕ}, n ∈ σ.cycleType → n ∣ orderOf σ
@Equiv.Perm.two_le_of_mem_cycleType : ∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] {σ : Equiv.Perm α}
  {n : ℕ}, n ∈ σ.cycleType → 2 ≤ n
@Equiv.Perm.lcm_cycleType : ∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] (σ : Equiv.Perm α),
  σ.cycleType.lcm = orderOf σ
@Multiset.eq_replicate_of_mem : ∀ {α : Type u_1} {a : α} {s : Multiset α},
  (∀ b ∈ s, b = a) → s = Multiset.replicate s.card a
@Equiv.tsum_eq : ∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α]
  (e : γ ≃ β) (f : β → α), ∑' (c : γ), f (e c) = ∑' (b : β), f b

